INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_IMPORTANCE', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_USES', 'skill', 'essential', 'Uses of oxygen in hospitals and nitrogen in fertilisers (Grade 6) are examples of science in health and farming. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
