INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.HAZARD_SYMBOLS', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_MANAGE', 'skill', 'essential', 'Grade 4 taught that pesticide tins are dangerous waste; their warning symbols are read here. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
