INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.FIRST_AID', 'SCIE.G4.FORCE_.HEAT.HEAT_SAFETY', 'skill', 'essential', 'Cooling a burn with clean water was first met in Grade 4 heat safety. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
