INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SCIENCE_SKILLS', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_FACTORS', 'skill', 'essential', 'Grade 5 floating tests (predict, test, record, conclude) are the child''s first practice of the science skills. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
