INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.SERIES_PARALLEL', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SOURCES', 'skill', 'essential', 'The child must know a cell is the source that pushes the current round both kinds of circuit. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
