INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_COMPONENTS.M_SC_SEPARATE', 'INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_COMPONENTS', 'Thinks biology, chemistry and physics are three separate subjects with nothing in common.', '{"question":"How are biology, chemistry and physics related in Integrated Science?","wrong_answer":"They are separate and never meet","correct_answer":"They are branches of one science, and many topics use all three"}'::jsonb, 'The child meets them as separate chapters.', 'Offer "They are separate and never meet" next to the right answer and ask the question again in a new context.', 'Take the heart: the blood is chemistry, the pump is physics, the organ is biology.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_COMPONENTS.M_SC_BIO_PLANTS', 'INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_COMPONENTS', 'Thinks biology is only about plants and animals in the field, and that the human body is not science.', '{"question":"Which branch studies the human heart?","wrong_answer":"None, the body is not science","correct_answer":"Biology"}'::jsonb, 'The child links biology only with plants and animals outdoors.', 'Offer "None, the body is not science" next to the right answer and ask the question again in a new context.', 'Name the branch for a snail, a mushroom, a heart and a germ: all biology.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_COMPONENTS.M_SC_CHEM_LAB', 'INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_COMPONENTS', 'Thinks chemistry is only the study of dangerous chemicals in a laboratory.', '{"question":"Which branch studies why soap removes dirt or why bread rises?","wrong_answer":"Only physics, because it is about doing","correct_answer":"Chemistry, which studies matter and how it changes"}'::jsonb, 'The child links chemistry with a laboratory and chemicals only.', 'Offer "Only physics, because it is about doing" next to the right answer and ask the question again in a new context.', 'List the changes in a kitchen: baking, rusting, burning charcoal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_IMPORTANCE.M_SM_LAB_ONLY', 'INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_IMPORTANCE', 'Thinks science is only done in laboratories by scientists in white coats.', '{"question":"Where is science used?","wrong_answer":"Only in a laboratory","correct_answer":"In homes, farms, hospitals, workshops and schools"}'::jsonb, 'The child pictures science as a place.', 'Offer "Only in a laboratory" next to the right answer and ask the question again in a new context.', 'List the science in a morning: a boiling kettle, soap, a bicycle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_IMPORTANCE.M_SM_HEALTH_ONLY', 'INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_IMPORTANCE', 'Thinks science only helps in hospitals and with medicines.', '{"question":"Which of these is a use of science in farming?","wrong_answer":"None, farming does not use science","correct_answer":"Better seeds and keeping soil healthy"}'::jsonb, 'The child links science with medicine and with machines.', 'Offer "None, farming does not use science" next to the right answer and ask the question again in a new context.', 'Ask how a farmer knows what to put on tired soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_IMPORTANCE.M_SM_NO_CAREER', 'INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_IMPORTANCE', 'Thinks only doctors and scientists have careers that use science.', '{"question":"Which job uses science?","wrong_answer":"Only a doctor","correct_answer":"A nurse, an engineer or a laboratory technician"}'::jsonb, 'The child knows a few science jobs and treats them as the only ones.', 'Offer "Only a doctor" next to the right answer and ask the question again in a new context.', 'Ask the child to name the people who built the school: engineers, electricians, surveyors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_COMPONENTS.M_SC_PHYSICS_MATHS', 'INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_COMPONENTS', 'Thinks physics is only sums and formulas, not the study of energy, forces, light and sound.', '{"question":"Which branch of science studies how a bicycle brake stops the wheel?","wrong_answer":"Mathematics","correct_answer":"Physics"}'::jsonb, 'Has heard physics described as a hard subject with calculations.', 'Offer "Mathematics" next to the right answer and ask the question again in a new context.', 'List physics topics the child already knows from Grades 4-6: force, light, sound, heat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_IMPORTANCE.M_SM_FARM_NOT_SCIENCE', 'INTE.G7.SCIENT.INTRODUCTION_TO_INTEGRAT.SCI_IMPORTANCE', 'Thinks farming is tradition, not science, so fertilisers, seed choice and pest control have nothing to do with science.', '{"question":"How does science help a maize farmer?","wrong_answer":"It does not; farming is done the old way","correct_answer":"Through better seed, the right fertiliser, soil testing and pest control"}'::jsonb, 'Sees science as a school subject separate from work at home.', 'Offer "It does not; farming is done the old way" next to the right answer and ask the question again in a new context.', 'Read a fertiliser bag and a certified seed packet with the class: science on the label.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.HAZARD_SYMBOLS.M_HS_FLAME_FIRE', 'INTE.G7.SCIENT.LABORATORY_SAFETY.HAZARD_SYMBOLS', 'Thinks the flame symbol on a bottle means it is used for fires or can be put on a fire.', '{"question":"A bottle shows a flame symbol. What does it warn?","wrong_answer":"It is used to make a fire","correct_answer":"It catches fire easily"}'::jsonb, 'The child reads the picture as an instruction, not a warning.', 'Offer "It is used to make a fire" next to the right answer and ask the question again in a new context.', 'Show a spirit bottle and say why it is kept far from the stove.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.HAZARD_SYMBOLS.M_HS_SKULL_DEAD', 'INTE.G7.SCIENT.LABORATORY_SAFETY.HAZARD_SYMBOLS', 'Thinks the skull symbol means the substance is for killing dead things or is safe to throw away.', '{"question":"A bottle shows a skull and crossbones. What does it warn?","wrong_answer":"Dead things are inside","correct_answer":"It is toxic, so it is poisonous"}'::jsonb, 'The child reads the picture literally.', 'Offer "Dead things are inside" next to the right answer and ask the question again in a new context.', 'Say what happens if a child swallows or breathes it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.HAZARD_SYMBOLS.M_HS_CORROSIVE_TOXIC', 'INTE.G7.SCIENT.LABORATORY_SAFETY.HAZARD_SYMBOLS', 'Mixes up corrosive and toxic and thinks both mean poison.', '{"question":"A bottle shows a hand and a metal being eaten away. What does it warn?","wrong_answer":"It is poisonous when swallowed","correct_answer":"It is corrosive, so it eats away skin and metal"}'::jsonb, 'The child gives one meaning to every danger sign.', 'Offer "It is poisonous when swallowed" next to the right answer and ask the question again in a new context.', 'Drip a weak acid on a rusty nail and watch it fizz; say what it would do to skin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.LAB_ACCIDENTS.M_LA_TASTE_SAFE', 'INTE.G7.SCIENT.LABORATORY_SAFETY.LAB_ACCIDENTS', 'Thinks it is fine to taste or smell a chemical to find out what it is.', '{"question":"A learner wants to know what a clear liquid is. What should she do?","wrong_answer":"Taste a drop to find out","correct_answer":"Ask the teacher and read the label"}'::jsonb, 'The child tastes foods to learn about them.', 'Offer "Taste a drop to find out" next to the right answer and ask the question again in a new context.', 'Say why a kitchen container with a laboratory liquid is dangerous.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.LAB_ACCIDENTS.M_LA_POINT_TUBE', 'INTE.G7.SCIENT.LABORATORY_SAFETY.LAB_ACCIDENTS', 'Thinks a test tube can be pointed at a neighbour while heating, because it will not spit.', '{"question":"How should you hold a test tube while heating it?","wrong_answer":"Pointing it at a friend so you can both see","correct_answer":"Pointing it away from everyone, and moving it gently"}'::jsonb, 'The child cannot see the liquid shoot out.', 'Offer "Pointing it at a friend so you can both see" next to the right answer and ask the question again in a new context.', 'Heat water in a tube behind a screen and watch the spit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.LAB_ACCIDENTS.M_LA_CARELESS_ONLY', 'INTE.G7.SCIENT.LABORATORY_SAFETY.LAB_ACCIDENTS', 'Thinks accidents only happen to careless people and cannot be prevented by rules.', '{"question":"Why do laboratories have rules?","wrong_answer":"Only careless people have accidents, so rules are not needed","correct_answer":"Rules stop accidents before they happen"}'::jsonb, 'The child thinks of accidents as bad luck.', 'Offer "Only careless people have accidents, so rules are not needed" next to the right answer and ask the question again in a new context.', 'List one rule for each accident: walking, tying hair, wearing a coat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.FIRST_AID.M_FA_BUTTER_BURN', 'INTE.G7.SCIENT.LABORATORY_SAFETY.FIRST_AID', 'Thinks butter, toothpaste or ash should be put on a burn.', '{"question":"A learner burns her hand on a hot beaker. What is the first thing to do?","wrong_answer":"Rub butter on the burn","correct_answer":"Hold it under cool running water for ten minutes"}'::jsonb, 'The child has seen home remedies.', 'Offer "Rub butter on the burn" next to the right answer and ask the question again in a new context.', 'Say why a cream on a hot burn keeps the heat in and can bring germs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.FIRST_AID.M_FA_VOMIT', 'INTE.G7.SCIENT.LABORATORY_SAFETY.FIRST_AID', 'Thinks a child who swallowed a chemical should be made to vomit.', '{"question":"A child swallows a harmful liquid. What should the helper do?","wrong_answer":"Make the child vomit at once","correct_answer":"Call the teacher, say what was swallowed and get the child to hospital"}'::jsonb, 'The child has heard of "throwing it up".', 'Offer "Make the child vomit at once" next to the right answer and ask the question again in a new context.', 'Say that some liquids burn the throat a second time on the way up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.FIRST_AID.M_FA_CUT_WASH', 'INTE.G7.SCIENT.LABORATORY_SAFETY.FIRST_AID', 'Thinks a deep cut should be left open to dry, or covered only after it stops bleeding on its own.', '{"question":"A learner cuts her finger on broken glass and it bleeds. What is the first step?","wrong_answer":"Leave it open to dry in the air","correct_answer":"Press a clean cloth on it and raise the hand"}'::jsonb, 'The child thinks drying stops bleeding.', 'Offer "Leave it open to dry in the air" next to the right answer and ask the question again in a new context.', 'Demonstrate pressure on a model: blood stops where the vessel is squeezed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.HAZARD_SYMBOLS.M_HS_NO_SYMBOL_SAFE', 'INTE.G7.SCIENT.LABORATORY_SAFETY.HAZARD_SYMBOLS', 'Thinks a container with no hazard symbol is always safe to drink from or touch.', '{"question":"A bottle in the laboratory has no label at all. Is it safe to smell or taste?","wrong_answer":"Yes, there is no danger sign","correct_answer":"No: an unlabelled substance must never be smelt, tasted or used; tell the teacher"}'::jsonb, 'Reads "no warning" as "safe".', 'Offer "Yes, there is no danger sign" next to the right answer and ask the question again in a new context.', 'Show two identical clear liquids: water and a cleaning solution. They look the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.LAB_ACCIDENTS.M_LA_RUN_EXIT', 'INTE.G7.SCIENT.LABORATORY_SAFETY.LAB_ACCIDENTS', 'Thinks running is the quickest and safest way to leave the laboratory in an emergency.', '{"question":"There is a small fire in the laboratory. How should learners leave?","wrong_answer":"Run out as fast as possible","correct_answer":"Walk quickly in a line to the exit, following the teacher"}'::jsonb, 'Thinks speed is all that matters.', 'Offer "Run out as fast as possible" next to the right answer and ask the question again in a new context.', 'Practise a fire drill: running causes falls and broken glassware.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_SAFETY.FIRST_AID.M_FA_EYE_RUB', 'INTE.G7.SCIENT.LABORATORY_SAFETY.FIRST_AID', 'Thinks a chemical splashed in the eye should be rubbed out with the hand.', '{"question":"A drop of a chemical splashes into a learner''s eye. What should be done first?","wrong_answer":"Rub the eye to get it out","correct_answer":"Rinse the eye with plenty of clean running water and tell the teacher"}'::jsonb, 'Rubs an eye by habit when something gets in it.', 'Offer "Rub the eye to get it out" next to the right answer and ask the question again in a new context.', 'Act out rinsing at a tap with the eye held open for several minutes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SCIENCE_SKILLS.M_SS_PREDICT_RESULT', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SCIENCE_SKILLS', 'Thinks a prediction is the result that happened.', '{"question":"What is a prediction?","wrong_answer":"What happened in the test","correct_answer":"What you expect to happen before you test"}'::jsonb, 'The child mixes before and after.', 'Offer "What happened in the test" next to the right answer and ask the question again in a new context.', 'Write the prediction before the test and read it out afterwards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SCIENCE_SKILLS.M_SS_OBSERVE_EYES', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SCIENCE_SKILLS', 'Thinks observing means only looking with the eyes.', '{"question":"Which of these is observing?","wrong_answer":"Only looking","correct_answer":"Using the senses safely, such as looking, listening and feeling"}'::jsonb, 'The child links observing to eyes.', 'Offer "Only looking" next to the right answer and ask the question again in a new context.', 'Observe a bell: see it, hear it, feel the vibration.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SCIENCE_SKILLS.M_SS_CONCLUSION_GUESS', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SCIENCE_SKILLS', 'Thinks a conclusion is a guess made before testing.', '{"question":"Which statement is a conclusion?","wrong_answer":"I think iron is magnetic","correct_answer":"The nail was pulled to the magnet, so iron is magnetic"}'::jsonb, 'The child mixes a hypothesis and a conclusion.', 'Offer "I think iron is magnetic" next to the right answer and ask the question again in a new context.', 'Say that a conclusion has to point at the results.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.APPARATUS_USE.M_AU_BEAKER_EXACT', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.APPARATUS_USE', 'Thinks a beaker measures liquid as exactly as a measuring cylinder.', '{"question":"Which apparatus gives the most exact volume of a liquid?","wrong_answer":"A beaker","correct_answer":"A measuring cylinder"}'::jsonb, 'The child sees the marks on a beaker.', 'Offer "A beaker" next to the right answer and ask the question again in a new context.', 'Pour 50 ml into both and compare how well the line is read.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.APPARATUS_USE.M_AU_READ_TOP', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.APPARATUS_USE', 'Reads a measuring cylinder at the top of the curve or from above.', '{"question":"How should you read the volume in a measuring cylinder?","wrong_answer":"From above, at the top of the liquid","correct_answer":"At eye level, at the bottom of the curve"}'::jsonb, 'The child reads the number nearest the top.', 'Offer "From above, at the top of the liquid" next to the right answer and ask the question again in a new context.', 'Look at the curve from a low, level and a high angle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.APPARATUS_USE.M_AU_YELLOW_FLAME', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.APPARATUS_USE', 'Thinks the hottest Bunsen flame is the yellow one, or that the air hole should always stay closed.', '{"question":"Which Bunsen flame is the hottest and cleanest for heating?","wrong_answer":"The yellow flame, because it is bright","correct_answer":"The blue flame with the air hole open"}'::jsonb, 'The child links bright colour with heat.', 'Offer "The yellow flame, because it is bright" next to the right answer and ask the question again in a new context.', 'Hold a tile over each flame: the yellow one leaves black soot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_BASE.M_SB_GRAM', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_BASE', 'Gives the gram as the SI unit of mass.', '{"question":"What is the SI unit of mass?","wrong_answer":"The gram","correct_answer":"The kilogram"}'::jsonb, 'The child uses grams on the kitchen scale.', 'Offer "The gram" next to the right answer and ask the question again in a new context.', 'Read a packet that says 1 kg and one that says 500 g.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_BASE.M_SB_MASS_WEIGHT', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_BASE', 'Uses mass and weight as the same thing, and gives the weight in kilograms.', '{"question":"Which quantity is measured in kilograms?","wrong_answer":"Weight","correct_answer":"Mass"}'::jsonb, 'Shops say "weight" for how heavy something is.', 'Offer "Weight" next to the right answer and ask the question again in a new context.', 'Say that mass is how much matter there is, and weight is the pull on it, in newtons.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_BASE.M_SB_CELSIUS_SI', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_BASE', 'Gives the degree Celsius as the SI unit of temperature.', '{"question":"What is the SI unit of temperature?","wrong_answer":"The degree Celsius","correct_answer":"The kelvin"}'::jsonb, 'The child uses a Celsius thermometer.', 'Offer "The degree Celsius" next to the right answer and ask the question again in a new context.', 'Show that 0 degrees Celsius is 273 kelvin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_DERIVED.M_SD_LITRE_SI', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_DERIVED', 'Gives the litre as the SI unit of volume.', '{"question":"What is the SI unit of volume?","wrong_answer":"The litre","correct_answer":"The cubic metre"}'::jsonb, 'The child pours drinks measured in litres.', 'Offer "The litre" next to the right answer and ask the question again in a new context.', 'Say that one cubic metre is a box one metre long, wide and high.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_DERIVED.M_SD_AREA_M', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_DERIVED', 'Gives area in metres, not square metres.', '{"question":"A floor is 4 m long and 3 m wide. What is its area?","wrong_answer":"12 m","correct_answer":"12 m2"}'::jsonb, 'The child forgets that area is length times length.', 'Offer "12 m" next to the right answer and ask the question again in a new context.', 'Cover the floor with one-metre squares and count them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_DERIVED.M_SD_SPEED_M', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_DERIVED', 'Gives speed in metres or in seconds, without both.', '{"question":"Which is the unit of speed?","wrong_answer":"Metres","correct_answer":"Metres per second"}'::jsonb, 'The child names only the distance part.', 'Offer "Metres" next to the right answer and ask the question again in a new context.', 'Say a boy runs 100 m in 20 s: the speed is 5 metres in each second.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SCIENCE_SKILLS.M_SS_ONE_TEST_ENOUGH', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SCIENCE_SKILLS', 'Thinks one test is enough to draw a conclusion.', '{"question":"A learner drops one stone in water, it sinks, and she concludes all stones sink. Is this a good conclusion?","wrong_answer":"Yes, she tested it","correct_answer":"No: test several stones (pumice floats) before concluding"}'::jsonb, 'Has seen one result and generalises.', 'Offer "Yes, she tested it" next to the right answer and ask the question again in a new context.', 'Test five different stones, including pumice if the school has one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.APPARATUS_USE.M_AU_THERMOMETER_SHAKE_READ', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.APPARATUS_USE', 'Takes the thermometer out of the liquid before reading it.', '{"question":"How should you read the temperature of hot water with a thermometer?","wrong_answer":"Take it out and read it in the air","correct_answer":"Read it while the bulb is still in the water"}'::jsonb, 'Wants to see the scale up close and does not know the reading changes in air.', 'Offer "Take it out and read it in the air" next to the right answer and ask the question again in a new context.', 'Read a thermometer in warm water, then lift it out and watch the reading drop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_BASE.M_SB_MINUTE_SI', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_BASE', 'Gives the minute or the hour as the SI unit of time.', '{"question":"What is the SI unit of time?","wrong_answer":"The minute","correct_answer":"The second"}'::jsonb, 'Uses the unit seen on clocks every day.', 'Offer "The minute" next to the right answer and ask the question again in a new context.', 'List the base units side by side: metre, kilogram, second, kelvin, ampere.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_DERIVED.M_SD_DENSITY_UNIT', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_DERIVED', 'Gives the unit of density as kilograms only, without the volume.', '{"question":"What is the SI unit of density?","wrong_answer":"kg","correct_answer":"kg/m³ (kilograms per cubic metre)"}'::jsonb, 'Remembers density "has to do with mass" and forgets it is mass per volume.', 'Offer "kg" next to the right answer and ask the question again in a new context.', 'Build the unit from the formula: density = mass divided by volume, so kg divided by m³.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.MIXTURES.HOMOGENEOUS_SOLUTION.M_HM_DISAPPEAR', 'INTE.G7.MIXTUR.MIXTURES.HOMOGENEOUS_SOLUTION', 'Thinks the salt has disappeared when it dissolves in water.', '{"question":"Salt is stirred into water until it cannot be seen. Where is the salt?","wrong_answer":"It has gone, it disappeared","correct_answer":"It is still there, spread through the water"}'::jsonb, 'The child can no longer see the solid.', 'Offer "It has gone, it disappeared" next to the right answer and ask the question again in a new context.', 'Taste a drop, or leave the water to evaporate and look at the white crystals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.MIXTURES.HOMOGENEOUS_SOLUTION.M_HM_MUDDY_SOLUTION', 'INTE.G7.MIXTUR.MIXTURES.HOMOGENEOUS_SOLUTION', 'Thinks muddy water is a solution because the soil is mixed in.', '{"question":"Which of these is a solution?","wrong_answer":"Muddy water","correct_answer":"Salt dissolved in water"}'::jsonb, 'The child links mixing with dissolving.', 'Offer "Muddy water" next to the right answer and ask the question again in a new context.', 'Leave muddy water to stand: the soil settles. Salty water stays clear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.MIXTURES.HOMOGENEOUS_SOLUTION.M_HM_SOLVENT_SOLUTE', 'INTE.G7.MIXTUR.MIXTURES.HOMOGENEOUS_SOLUTION', 'Mixes up solute and solvent.', '{"question":"In sugar dissolved in tea, which is the solvent?","wrong_answer":"The sugar","correct_answer":"The water in the tea"}'::jsonb, 'The child thinks the main thing in the cup is the solvent only if it is solid.', 'Offer "The sugar" next to the right answer and ask the question again in a new context.', 'Say that the solvent is the liquid that dissolves, and the solute is what dissolves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.MIXTURES.SEPARATE_CHOICE.M_SE_FILTER_SALT', 'INTE.G7.MIXTUR.MIXTURES.SEPARATE_CHOICE', 'Thinks filtering separates salt from salt water.', '{"question":"Which method separates salt from salt water?","wrong_answer":"Filtering","correct_answer":"Evaporation"}'::jsonb, 'The child uses filtering for every mixture.', 'Offer "Filtering" next to the right answer and ask the question again in a new context.', 'Pour salt water through filter paper and taste it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.MIXTURES.SEPARATE_CHOICE.M_SE_EVAP_DISTIL', 'INTE.G7.MIXTUR.MIXTURES.SEPARATE_CHOICE', 'Does not tell evaporation from distillation: thinks evaporation also collects the water.', '{"question":"Which method lets you collect pure water from salt water?","wrong_answer":"Evaporation, which lets the water escape into the air","correct_answer":"Simple distillation, which cools the vapour back to liquid"}'::jsonb, 'The child stops at the vapour.', 'Offer "Evaporation, which lets the water escape into the air" next to the right answer and ask the question again in a new context.', 'Hold a cold plate above a boiling pot and watch the drops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.MIXTURES.SEPARATE_CHOICE.M_SE_CHROMA_COLOUR', 'INTE.G7.MIXTUR.MIXTURES.SEPARATE_CHOICE', 'Thinks chromatography separates mixtures by boiling.', '{"question":"How does chromatography separate the dyes in black ink?","wrong_answer":"By boiling the dyes off one at a time","correct_answer":"The dyes travel different distances up the paper"}'::jsonb, 'The child links separating with heating.', 'Offer "By boiling the dyes off one at a time" next to the right answer and ask the question again in a new context.', 'Run a felt-tip dot on a strip of paper and watch the colours split.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.MIXTURES.SEPARATE_USES.M_SU_SALT_FILTER', 'INTE.G7.MIXTUR.MIXTURES.SEPARATE_USES', 'Thinks sea salt is won by filtering the sea water.', '{"question":"How is salt won from sea water at the coast?","wrong_answer":"By filtering the sea water","correct_answer":"By letting the water evaporate in shallow pans"}'::jsonb, 'The child uses filtering for every mixture.', 'Offer "By filtering the sea water" next to the right answer and ask the question again in a new context.', 'Look at photos of the salt pans at Gongoni or Malindi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.MIXTURES.SEPARATE_USES.M_SU_OIL_ONE', 'INTE.G7.MIXTUR.MIXTURES.SEPARATE_USES', 'Thinks crude oil is one liquid that is simply poured into the tank.', '{"question":"How do we get petrol, diesel and paraffin from crude oil?","wrong_answer":"It already comes out of the ground as petrol, diesel and paraffin","correct_answer":"By fractional distillation, which uses their different boiling points"}'::jsonb, 'The child has not seen crude oil.', 'Offer "It already comes out of the ground as petrol, diesel and paraffin" next to the right answer and ask the question again in a new context.', 'Say that crude oil is a thick black mixture of many liquids.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.MIXTURES.SEPARATE_USES.M_SU_SCIENTISTS_ONLY', 'INTE.G7.MIXTUR.MIXTURES.SEPARATE_USES', 'Thinks separating mixtures is only done in laboratories.', '{"question":"Where is separating of mixtures used?","wrong_answer":"Only in laboratories","correct_answer":"In homes and industry, for example making salt, tea and clean water"}'::jsonb, 'The child ties methods to the laboratory.', 'Offer "Only in laboratories" next to the right answer and ask the question again in a new context.', 'List the separating done in a kitchen: sieving flour, straining tea, evaporating to make salt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.MIXTURES.HOMOGENEOUS_SOLUTION.M_HM_SOLUTION_ONLY_WATER', 'INTE.G7.MIXTUR.MIXTURES.HOMOGENEOUS_SOLUTION', 'Thinks only water can be a solvent.', '{"question":"Nail polish is removed with a liquid called acetone. What is the acetone here?","wrong_answer":"Not a solvent; only water is a solvent","correct_answer":"The solvent: it dissolves the nail polish"}'::jsonb, 'Has only seen things dissolve in water.', 'Offer "Not a solvent; only water is a solvent" next to the right answer and ask the question again in a new context.', 'Show a grease stain dissolving in paraffin (teacher) but not in water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.MIXTURES.SEPARATE_CHOICE.M_SE_DISTIL_DESTROYS_SALT', 'INTE.G7.MIXTUR.MIXTURES.SEPARATE_CHOICE', 'Thinks distillation destroys the salt and only keeps the water.', '{"question":"After simple distillation of salt water, where is the salt?","wrong_answer":"It has been burnt away","correct_answer":"It is left behind in the flask"}'::jsonb, 'Focuses on the clean water collected and forgets what stays behind.', 'Offer "It has been burnt away" next to the right answer and ask the question again in a new context.', 'Look into the flask after distillation: white salt is left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.MIXTURES.SEPARATE_USES.M_SU_CHROMA_USELESS', 'INTE.G7.MIXTUR.MIXTURES.SEPARATE_USES', 'Thinks chromatography has no use outside school.', '{"question":"Where can chromatography be used outside school?","wrong_answer":"Nowhere, it is only a class activity","correct_answer":"To check dyes in food and inks, or test for banned substances"}'::jsonb, 'Has only seen it as a classroom activity with pens.', 'Offer "Nowhere, it is only a class activity" next to the right answer and ask the question again in a new context.', 'Show how food colours can be tested to see if they contain a banned dye.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.LITMUS_CLASSIFY.M_LC_BLUE_BASE', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.LITMUS_CLASSIFY', 'Thinks blue litmus paper turns more blue in a base, or red in a base.', '{"question":"What does blue litmus paper do in an acid?","wrong_answer":"It stays blue","correct_answer":"It turns red"}'::jsonb, 'The child learns the colours in the wrong order.', 'Offer "It stays blue" next to the right answer and ask the question again in a new context.', 'Dip blue litmus in lemon juice and watch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.LITMUS_CLASSIFY.M_LC_NEUTRAL_ACID', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.LITMUS_CLASSIFY', 'Thinks water, or any liquid that does not change litmus, must be an acid.', '{"question":"Pure water does not change either litmus paper. What is it?","wrong_answer":"An acid","correct_answer":"Neutral"}'::jsonb, 'The child knows only two groups.', 'Offer "An acid" next to the right answer and ask the question again in a new context.', 'Test pure water, lemon juice and soap solution on both papers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.LITMUS_CLASSIFY.M_LC_TASTE_TEST', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.LITMUS_CLASSIFY', 'Thinks you can find out whether a liquid is an acid or a base by tasting it.', '{"question":"How can you safely find out if a liquid is an acid or a base?","wrong_answer":"Taste a drop","correct_answer":"Test it with litmus paper"}'::jsonb, 'The child knows that lemon is sour.', 'Offer "Taste a drop" next to the right answer and ask the question again in a new context.', 'Say that strong ones burn the mouth and some are poisonous.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.INDICATOR_PLANT.M_IP_ONLY_LITMUS', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.INDICATOR_PLANT', 'Thinks only litmus paper can be used as an indicator.', '{"question":"Which of these can be used to make an indicator?","wrong_answer":"Only litmus from a shop","correct_answer":"Red cabbage, beetroot or hibiscus flowers"}'::jsonb, 'The child met only litmus paper.', 'Offer "Only litmus from a shop" next to the right answer and ask the question again in a new context.', 'Soak crushed hibiscus petals in warm water and add lemon juice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.INDICATOR_PLANT.M_IP_SAME_COLOUR', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.INDICATOR_PLANT', 'Thinks the extract keeps one colour whatever it is tested with.', '{"question":"A red cabbage extract is added to vinegar and then to soap solution. What happens?","wrong_answer":"It stays the same colour in both","correct_answer":"It changes to a different colour in each"}'::jsonb, 'The child expects an extract to be a plain colour.', 'Offer "It stays the same colour in both" next to the right answer and ask the question again in a new context.', 'Test the extract on lemon, vinegar, soap and water side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.INDICATOR_PLANT.M_IP_STRONG_CHEM', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.INDICATOR_PLANT', 'Thinks making an indicator needs strong chemicals.', '{"question":"How is an indicator made from red cabbage?","wrong_answer":"By soaking it in a strong acid","correct_answer":"By crushing it and soaking it in warm water, then straining it"}'::jsonb, 'The child links science with chemicals.', 'Offer "By soaking it in a strong acid" next to the right answer and ask the question again in a new context.', 'Make it with warm water and a cloth strainer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_PROPERTIES.M_AP_BASE_SWEET', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_PROPERTIES', 'Thinks bases taste sweet or have no taste.', '{"question":"What do bases feel and taste like?","wrong_answer":"Sweet","correct_answer":"Bitter and soapy"}'::jsonb, 'The child has no everyday word for bitter.', 'Offer "Sweet" next to the right answer and ask the question again in a new context.', 'Say how soap tastes if some gets in the mouth (do not test).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_PROPERTIES.M_AP_ALL_BURN', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_PROPERTIES', 'Thinks all acids burn skin.', '{"question":"Which of these is true?","wrong_answer":"All acids burn skin","correct_answer":"Strong acids can burn skin, and weak acids such as lemon juice are in food"}'::jsonb, 'The child knows about battery acid.', 'Offer "All acids burn skin" next to the right answer and ask the question again in a new context.', 'List acids we eat: lemon, vinegar, tamarind.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_PROPERTIES.M_AP_BASE_OPPOSITE', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_PROPERTIES', 'Thinks a base is a poison and cancels an acid like an antidote.', '{"question":"What is a base?","wrong_answer":"A poison that works against acids","correct_answer":"A substance that is bitter and turns red litmus blue"}'::jsonb, 'The child hears of "neutralising".', 'Offer "A poison that works against acids" next to the right answer and ask the question again in a new context.', 'Say that strong bases burn as well.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_USES.M_AU2_ANTACID_ACID', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_USES', 'Thinks an acid is the cure for heartburn.', '{"question":"Which substance eases heartburn from too much stomach acid?","wrong_answer":"More acid, such as vinegar","correct_answer":"An antacid, which is a base"}'::jsonb, 'The child thinks a cure must be a medicine of the same kind.', 'Offer "More acid, such as vinegar" next to the right answer and ask the question again in a new context.', 'Say that an antacid tablet tastes chalky, not sour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_USES.M_AU2_SOIL_ASH', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_USES', 'Thinks wood ash is spread on soil only to feed it.', '{"question":"Why is lime or wood ash sometimes added to soil?","wrong_answer":"Because the soil is too hungry","correct_answer":"Because the soil is too acidic"}'::jsonb, 'The child links ash with fertiliser.', 'Offer "Because the soil is too hungry" next to the right answer and ask the question again in a new context.', 'Say what an indicator shows about acidic soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_USES.M_AU2_STRONGER', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_USES', 'Thinks a stronger acid or base is always better for a job.', '{"question":"Why is vinegar and not battery acid used on chips?","wrong_answer":"The strong one would be better","correct_answer":"Strong acids burn and are dangerous"}'::jsonb, 'The child thinks strength means power.', 'Offer "The strong one would be better" next to the right answer and ask the question again in a new context.', 'List the strength of the acid in each house item.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.LITMUS_CLASSIFY.M_LC_SAME_PAPER_BOTH', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.LITMUS_CLASSIFY', 'Thinks one colour of litmus paper is enough to tell acids, bases and neutral solutions apart.', '{"question":"Blue litmus stays blue in a solution. What can you say?","wrong_answer":"It is a base","correct_answer":"It is not an acid: it is a base or neutral; test with red litmus too"}'::jsonb, 'Does not see that "no change" leaves two options.', 'Offer "It is a base" next to the right answer and ask the question again in a new context.', 'Test water and soap with blue litmus (no change for both), then with red litmus.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.INDICATOR_PLANT.M_IP_ANY_LEAF', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.INDICATOR_PLANT', 'Thinks any green leaf makes a good indicator.', '{"question":"Which plant extract makes a good acid-base indicator?","wrong_answer":"Any green leaf, such as sukuma","correct_answer":"A strongly coloured one, such as red cabbage or purple flowers, that changes colour"}'::jsonb, 'Thinks any plant juice will show a change.', 'Offer "Any green leaf, such as sukuma" next to the right answer and ask the question again in a new context.', 'Test sukuma juice and red cabbage juice in vinegar and soap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_PROPERTIES.M_AP_ACID_ALWAYS_LIQUID', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_PROPERTIES', 'Thinks all acids are liquids, so a solid such as citric acid powder cannot be an acid.', '{"question":"Citric acid is a white powder used in cooking. Can a powder be an acid?","wrong_answer":"No, acids are liquids","correct_answer":"Yes: it dissolves to make an acidic solution"}'::jsonb, 'Has only seen acids as liquids in bottles.', 'Offer "No, acids are liquids" next to the right answer and ask the question again in a new context.', 'Dissolve a pinch of citric acid in water and test with blue litmus.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_USES.M_AU2_BLEACH_FOOD', 'INTE.G7.MIXTUR.ACIDS_BASES_AND_INDICATO.AB_USES', 'Thinks a cleaning base such as bleach can be used to wash fruit to make it safer.', '{"question":"Should fruit be washed in bleach to make it safe?","wrong_answer":"Yes, bleach kills germs","correct_answer":"No: wash fruit in clean water; bleach is for cleaning surfaces"}'::jsonb, 'Knows bleach kills germs and applies it everywhere.', 'Offer "Yes, bleach kills germs" next to the right answer and ask the question again in a new context.', 'Read the bleach label with the class: not for food.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_MALE.M_RM_TESTIS_URINE', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_MALE', 'Thinks the testes make urine, or that sperm are made in the bladder.', '{"question":"Which part of the male reproductive system makes sperm?","wrong_answer":"The bladder","correct_answer":"The testes"}'::jsonb, 'The child links all private parts with passing urine.', 'Offer "The bladder" next to the right answer and ask the question again in a new context.', 'Draw the urinary system and the reproductive system in two colours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_MALE.M_RM_URETHRA_ONE', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_MALE', 'Thinks the urethra carries only urine, or only sperm.', '{"question":"What does the urethra carry in a man?","wrong_answer":"Only urine","correct_answer":"Urine at one time and sperm at another"}'::jsonb, 'The child learns one job per tube.', 'Offer "Only urine" next to the right answer and ask the question again in a new context.', 'Name the tube and say it is the shared way out, used for one at a time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_MALE.M_RM_SCROTUM', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_MALE', 'Thinks the testes are inside the body in the stomach.', '{"question":"Where are the testes held?","wrong_answer":"Inside the stomach","correct_answer":"In the scrotum, outside the body"}'::jsonb, 'The child puts all organs inside.', 'Offer "Inside the stomach" next to the right answer and ask the question again in a new context.', 'Say why they are held outside the body: it is cooler there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_FEMALE.M_RF_STOMACH_BABY', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_FEMALE', 'Thinks a baby grows in the stomach.', '{"question":"Where does a baby grow before birth?","wrong_answer":"In the stomach","correct_answer":"In the uterus"}'::jsonb, 'The child sees the mother''s belly grow.', 'Offer "In the stomach" next to the right answer and ask the question again in a new context.', 'Compare the position of the stomach and the uterus on a chart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_FEMALE.M_RF_OVARY_UTERUS', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_FEMALE', 'Mixes up the ovary and the uterus.', '{"question":"Which part makes and stores the eggs?","wrong_answer":"The uterus","correct_answer":"The ovaries"}'::jsonb, 'The child knows the words but not the jobs.', 'Offer "The uterus" next to the right answer and ask the question again in a new context.', 'Label two parts and say what each is for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_FEMALE.M_RF_CERVIX_VAGINA', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_FEMALE', 'Thinks the cervix is the opening to the outside.', '{"question":"What is the cervix?","wrong_answer":"The opening to the outside of the body","correct_answer":"The narrow neck of the uterus"}'::jsonb, 'The child mixes up the cervix and the vagina.', 'Offer "The opening to the outside of the body" next to the right answer and ask the question again in a new context.', 'Trace the path on a chart from the uterus to the outside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_CHANGES.M_AC_BOYS_ONLY', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_CHANGES', 'Thinks only boys grow quickly and only girls change in adolescence.', '{"question":"Which changes happen to both boys and girls?","wrong_answer":"Only girls change","correct_answer":"Quick growth, more sweat, hair under the arms and pimples"}'::jsonb, 'The child learns the lists in separate groups.', 'Offer "Only girls change" next to the right answer and ask the question again in a new context.', 'List changes in two columns and mark the shared ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_CHANGES.M_AC_SAME_AGE', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_CHANGES', 'Thinks all children change at exactly the same age, so a late one is sick.', '{"question":"Faith has not begun to change but her friend has. What can you tell her?","wrong_answer":"She must be sick","correct_answer":"Everyone changes at a different age, and that is normal"}'::jsonb, 'The child compares with friends.', 'Offer "She must be sick" next to the right answer and ask the question again in a new context.', 'Compare heights in a class: they differ at every age.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_CHANGES.M_AC_PERIOD_ILLNESS', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_CHANGES', 'Thinks periods are an illness or a punishment.', '{"question":"What is menstruation?","wrong_answer":"A sickness that girls get","correct_answer":"A normal monthly flow of blood from the uterus"}'::jsonb, 'The child has heard it described as bad or dirty.', 'Offer "A sickness that girls get" next to the right answer and ask the question again in a new context.', 'Say that it is a sign that the body is growing up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_COPING.M_AC2_SQUEEZE', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_COPING', 'Thinks squeezing pimples or using strong soap is the way to clear them.', '{"question":"Which is the best way to care for skin with pimples?","wrong_answer":"Squeeze them to clear them","correct_answer":"Wash the face gently each day and do not squeeze"}'::jsonb, 'The child wants a quick fix.', 'Offer "Squeeze them to clear them" next to the right answer and ask the question again in a new context.', 'Say that squeezing can spread germs and leave marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_COPING.M_AC2_KEEP_QUIET', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_COPING', 'Thinks worries and mood swings should be kept to oneself.', '{"question":"A learner feels very sad and angry, and does not know why. What is a good step?","wrong_answer":"Keep it to herself","correct_answer":"Talk to a parent, teacher or counsellor she trusts"}'::jsonb, 'The child thinks it is shameful.', 'Offer "Keep it to herself" next to the right answer and ask the question again in a new context.', 'Say who in school can help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_COPING.M_AC2_PADS', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_COPING', 'Thinks one pad can be used all day, or that periods mean missing school.', '{"question":"What should a girl do about pads during her period?","wrong_answer":"Use one pad all day, and stay home","correct_answer":"Change a clean pad often, and wash well"}'::jsonb, 'The child lacks practical information.', 'Offer "Use one pad all day, and stay home" next to the right answer and ask the question again in a new context.', 'Say that a clean pad changed often is healthy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_MALE.M_RM_SPERM_DUCT_BLADDER', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_MALE', 'Thinks the sperm duct carries urine from the bladder.', '{"question":"What does the sperm duct carry?","wrong_answer":"Urine from the bladder","correct_answer":"Sperm from the testes to the urethra"}'::jsonb, 'Knows both pass out through the urethra and mixes their paths.', 'Offer "Urine from the bladder" next to the right answer and ask the question again in a new context.', 'Trace both paths on a diagram in two colours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_FEMALE.M_RF_EGG_EVERY_DAY', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.REPRO_FEMALE', 'Thinks an ovary releases an egg every day.', '{"question":"How often does an ovary usually release an egg?","wrong_answer":"Every day","correct_answer":"About once a month"}'::jsonb, 'Has not met the idea of a monthly cycle.', 'Offer "Every day" next to the right answer and ask the question again in a new context.', 'Use a calendar to show a cycle of about 28 days.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_CHANGES.M_AC_VOICE_GIRLS_NONE', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_CHANGES', 'Thinks girls have no physical changes except periods.', '{"question":"Name one change in girls during adolescence other than periods.","wrong_answer":"There are none","correct_answer":"Breasts develop, hips widen, hair grows under the arms, a growth spurt"}'::jsonb, 'Hears most about periods and forgets other changes.', 'Offer "There are none" next to the right answer and ask the question again in a new context.', 'List changes for boys and girls side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_COPING.M_AC2_SKIP_MEALS', 'INTE.G7.LIVING.HUMAN_REPRODUCTIVE_SYSTE.ADOLESCENCE_COPING', 'Thinks skipping meals is a good way to deal with weight gain in adolescence.', '{"question":"A learner gains weight in a growth spurt. Is skipping breakfast a good idea?","wrong_answer":"Yes, it keeps the weight down","correct_answer":"No: eat balanced meals and stay active; growth needs food"}'::jsonb, 'Sees weight gain as a problem to fix by eating less.', 'Offer "Yes, it keeps the weight down" next to the right answer and ask the question again in a new context.', 'Link to growth: the body is building bone and muscle and needs food.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.EXCRETION_ORGANS.M_EO_FAECES', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.EXCRETION_ORGANS', 'Thinks faeces are excreted waste in the same way as urine and sweat.', '{"question":"Which of these is excreted by the body?","wrong_answer":"Faeces","correct_answer":"Urine"}'::jsonb, 'The child lists everything that leaves the body.', 'Offer "Faeces" next to the right answer and ask the question again in a new context.', 'Say that faeces are food that was never taken into the body''s cells.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.EXCRETION_ORGANS.M_EO_LUNGS_O2', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.EXCRETION_ORGANS', 'Thinks the lungs only take in air and do not remove waste.', '{"question":"What waste gas do the lungs remove?","wrong_answer":"Oxygen","correct_answer":"Carbon dioxide"}'::jsonb, 'The child thinks breathing out gives back only air.', 'Offer "Oxygen" next to the right answer and ask the question again in a new context.', 'Breathe onto a cold mirror and look at the water, and say CO2 is invisible.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.EXCRETION_ORGANS.M_EO_SKIN_ONLY_COOL', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.EXCRETION_ORGANS', 'Thinks sweat only cools the body and does not remove waste.', '{"question":"What does sweat carry out of the body?","wrong_answer":"Only heat","correct_answer":"Water and salts"}'::jsonb, 'The child links sweat with cooling only.', 'Offer "Only heat" next to the right answer and ask the question again in a new context.', 'Taste a drop on a hand after exercise (a safe sample): it is salty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.SKIN_PARTS.M_SK_EPIDERMIS_SWEAT', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.SKIN_PARTS', 'Thinks the epidermis makes sweat.', '{"question":"Which part of the skin makes sweat?","wrong_answer":"The epidermis","correct_answer":"The sweat gland"}'::jsonb, 'The child names the outer layer for everything.', 'Offer "The epidermis" next to the right answer and ask the question again in a new context.', 'Draw the layers and place the gland in the dermis.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.SKIN_PARTS.M_SK_PORE_BLOOD', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.SKIN_PARTS', 'Thinks sweat pores lead directly to the blood.', '{"question":"What is a sweat pore?","wrong_answer":"A hole that goes to the blood","correct_answer":"The tiny opening on the skin where sweat comes out"}'::jsonb, 'The child sees only holes.', 'Offer "A hole that goes to the blood" next to the right answer and ask the question again in a new context.', 'Look at the skin with a hand lens: tiny dots, no blood.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.SKIN_PARTS.M_SK_HAIR_EPI', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.SKIN_PARTS', 'Thinks hair grows from the epidermis, the layer on the surface.', '{"question":"Which layer holds the roots of the hairs?","wrong_answer":"The epidermis","correct_answer":"The dermis"}'::jsonb, 'The child sees hair coming from the surface.', 'Offer "The epidermis" next to the right answer and ask the question again in a new context.', 'Look at a plucked hair: the root end is bulb-shaped.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.URINARY_PARTS.M_UP_KIDNEY_STORE', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.URINARY_PARTS', 'Thinks the kidneys store urine.', '{"question":"Which part stores urine?","wrong_answer":"The kidney","correct_answer":"The bladder"}'::jsonb, 'The child thinks the kidney holds what it makes.', 'Offer "The kidney" next to the right answer and ask the question again in a new context.', 'Squeeze a balloon: it stores. A bean-shaped filter does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.URINARY_PARTS.M_UP_DRINK_BLADDER', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.URINARY_PARTS', 'Thinks a drink goes straight to the bladder.', '{"question":"What happens to water that we drink before it becomes urine?","wrong_answer":"It goes straight to the bladder","correct_answer":"It is taken into the blood and the kidneys clean the blood"}'::jsonb, 'The child links drinking with the need to urinate.', 'Offer "It goes straight to the bladder" next to the right answer and ask the question again in a new context.', 'Trace the drink: mouth, stomach, blood, kidney, bladder.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.URINARY_PARTS.M_UP_URETER_URETHRA', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.URINARY_PARTS', 'Mixes up the ureter and the urethra.', '{"question":"Which tube takes urine from the kidney to the bladder?","wrong_answer":"The urethra","correct_answer":"The ureter"}'::jsonb, 'The two words look alike.', 'Offer "The urethra" next to the right answer and ask the question again in a new context.', 'Say: the ureters are from the kidneys, two of them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.KIDNEY_HEALTH.M_KH_STONES_CATCH', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.KIDNEY_HEALTH', 'Thinks kidney problems are caught from other people.', '{"question":"How do kidney stones form?","wrong_answer":"They are caught from other people","correct_answer":"Minerals in urine stick together, often when little water is drunk"}'::jsonb, 'The child thinks of illnesses as infections.', 'Offer "They are caught from other people" next to the right answer and ask the question again in a new context.', 'Compare a sealed jar of salty water left to dry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.KIDNEY_HEALTH.M_KH_LESS_WATER', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.KIDNEY_HEALTH', 'Thinks drinking less water protects the kidneys.', '{"question":"What helps keep the kidneys healthy?","wrong_answer":"Drinking as little water as possible","correct_answer":"Drinking enough clean water"}'::jsonb, 'The child thinks the kidneys must rest.', 'Offer "Drinking as little water as possible" next to the right answer and ask the question again in a new context.', 'Say what colour urine is when little is drunk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.KIDNEY_HEALTH.M_KH_SKIN_RARE', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.KIDNEY_HEALTH', 'Thinks skin only needs washing when it looks dirty.', '{"question":"How often should the skin be cleaned?","wrong_answer":"Only when it looks dirty","correct_answer":"Every day, as sweat and dirt build up"}'::jsonb, 'The child cannot see the sweat and germs.', 'Offer "Only when it looks dirty" next to the right answer and ask the question again in a new context.', 'Smell clothes after a day of play.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.EXCRETION_ORGANS.M_EO_LIVER_NONE', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.EXCRETION_ORGANS', 'Does not count the liver as an organ that helps remove waste.', '{"question":"Which organ breaks down waste and old red cells in the body?","wrong_answer":"The stomach","correct_answer":"The liver"}'::jsonb, 'Has only heard of the kidneys, lungs and skin as excretory organs.', 'Offer "The stomach" next to the right answer and ask the question again in a new context.', 'Add the liver to the chart: it breaks down wastes so they can be removed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.SKIN_PARTS.M_SK_SKIN_ONE_LAYER', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.SKIN_PARTS', 'Thinks the skin is one thin layer like paper.', '{"question":"How many main layers does the skin have?","wrong_answer":"One","correct_answer":"Two main layers: the epidermis on top and the dermis below"}'::jsonb, 'Sees only the surface.', 'Offer "One" next to the right answer and ask the question again in a new context.', 'Look at a diagram of the skin cut through.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.URINARY_PARTS.M_UP_ONE_KIDNEY', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.URINARY_PARTS', 'Thinks people have one kidney.', '{"question":"How many kidneys does a person usually have?","wrong_answer":"One","correct_answer":"Two"}'::jsonb, 'Has heard "the kidney" in the singular.', 'Offer "One" next to the right answer and ask the question again in a new context.', 'Show the diagram: two kidneys at the back of the abdomen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.KIDNEY_HEALTH.M_KH_PAINKILLERS_SAFE', 'INTE.G7.LIVING.HUMAN_EXCRETORY_SYSTEM.KIDNEY_HEALTH', 'Thinks painkillers can be taken as often as wanted without harming the kidneys.', '{"question":"Is it safe to take painkillers every day without a health worker''s advice?","wrong_answer":"Yes, they are only for pain","correct_answer":"No: too many painkillers can harm the kidneys; take them as advised"}'::jsonb, 'Thinks medicines only do good.', 'Offer "Yes, they are only for pain" next to the right answer and ask the question again in a new context.', 'Read a painkiller packet: the dose and the warning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SOURCES.M_ES_SOCKET', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SOURCES', 'Thinks the socket or the wire in a house is the source of electricity.', '{"question":"Which of these is a source of electricity?","wrong_answer":"A power socket","correct_answer":"A dry cell or a generator"}'::jsonb, 'The child sees electricity come out of the wall.', 'Offer "A power socket" next to the right answer and ask the question again in a new context.', 'Follow a wire back from the socket to the pole.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SOURCES.M_ES_STORED_WIRE', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SOURCES', 'Thinks electricity is stored in the wires and used up from there.', '{"question":"Where does the electricity in a house come from?","wrong_answer":"It is stored in the wires of the house","correct_answer":"It is made at a power station and sent along wires"}'::jsonb, 'The child cannot see the power station.', 'Offer "It is stored in the wires of the house" next to the right answer and ask the question again in a new context.', 'Trace the line from the pole to the substation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SOURCES.M_ES_HYDRO_GEO', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SOURCES', 'Mixes up hydroelectric and geothermal power.', '{"question":"At Olkaria, steam from underground drives the generators. What is this called?","wrong_answer":"Hydroelectric power","correct_answer":"Geothermal power"}'::jsonb, 'The child links all power with water.', 'Offer "Hydroelectric power" next to the right answer and ask the question again in a new context.', 'Say that Masinga uses water from a dam and Olkaria uses steam from hot rocks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.CIRCUIT_BASICS.M_CB_ONE_WIRE', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.CIRCUIT_BASICS', 'Thinks one wire from the cell to the bulb is enough.', '{"question":"A bulb is joined to a cell by one wire. Will it light?","wrong_answer":"Yes, the current flows to the bulb","correct_answer":"No, it needs a complete loop of wires"}'::jsonb, 'The child thinks current flows from the cell to the bulb and stops.', 'Offer "Yes, the current flows to the bulb" next to the right answer and ask the question again in a new context.', 'Light a bulb with one wire and then with two.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.CIRCUIT_BASICS.M_CB_USED_UP', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.CIRCUIT_BASICS', 'Thinks the bulb uses up the current so less comes back to the cell.', '{"question":"Is the current the same going into the bulb and coming out?","wrong_answer":"No, the bulb uses it up","correct_answer":"Yes, the same current goes round the whole loop"}'::jsonb, 'The child thinks current is a thing that is consumed.', 'Offer "No, the bulb uses it up" next to the right answer and ask the question again in a new context.', 'Add a second meter after the bulb and watch both readings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.CIRCUIT_BASICS.M_CB_SWITCH_OPEN', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.CIRCUIT_BASICS', 'Thinks a switch that is open lets current pass.', '{"question":"When does a switch let current flow?","wrong_answer":"When it is open","correct_answer":"When it is closed"}'::jsonb, 'The child links "open" with "on".', 'Offer "When it is open" next to the right answer and ask the question again in a new context.', 'Close a switch in the circuit and watch the bulb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.SERIES_PARALLEL.M_SP_SERIES_STAY', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.SERIES_PARALLEL', 'Thinks that in a series circuit the other bulbs stay lit when one is removed.', '{"question":"Two bulbs are in series. One is removed. What happens to the other?","wrong_answer":"It stays lit","correct_answer":"It goes out"}'::jsonb, 'The child thinks each bulb has its own path.', 'Offer "It stays lit" next to the right answer and ask the question again in a new context.', 'Remove a bulb from a string of fairy lights.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.SERIES_PARALLEL.M_SP_PARALLEL_DIM', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.SERIES_PARALLEL', 'Thinks bulbs in parallel are dimmer than bulbs in series.', '{"question":"Which is brighter, two bulbs in series or two bulbs in parallel?","wrong_answer":"Series, because the current goes through both","correct_answer":"Parallel, because each has its own path to the cell"}'::jsonb, 'The child thinks sharing means getting less.', 'Offer "Series, because the current goes through both" next to the right answer and ask the question again in a new context.', 'Compare both circuits with the same cell.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.SERIES_PARALLEL.M_SP_HOUSE_SERIES', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.SERIES_PARALLEL', 'Thinks house lights are wired in series.', '{"question":"How are the lights in a house wired?","wrong_answer":"In series, in one loop","correct_answer":"In parallel, so each light can work alone"}'::jsonb, 'The child does not see the wiring.', 'Offer "In series, in one loop" next to the right answer and ask the question again in a new context.', 'Switch off one lamp at home and see that the others stay on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.APPLIANCES.M_AP2_MAKES_ELEC', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.APPLIANCES', 'Thinks an appliance makes electricity.', '{"question":"What does an electric fan do with electricity?","wrong_answer":"It makes electricity","correct_answer":"It changes electricity into movement"}'::jsonb, 'The child thinks anything electric makes electricity.', 'Offer "It makes electricity" next to the right answer and ask the question again in a new context.', 'Unplug the fan and see that it stops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.APPLIANCES.M_AP2_RADIO_NONE', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.APPLIANCES', 'Thinks a radio, speaker or television gives no energy except light.', '{"question":"What energy does a loudspeaker give out?","wrong_answer":"Heat","correct_answer":"Sound"}'::jsonb, 'The child expects each appliance to give heat.', 'Offer "Heat" next to the right answer and ask the question again in a new context.', 'Touch a speaker cone gently when music plays: it vibrates.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.APPLIANCES.M_AP2_FRIDGE_COLD', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.APPLIANCES', 'Thinks a refrigerator makes cold and gives out nothing.', '{"question":"What does a refrigerator do with electricity?","wrong_answer":"It makes cold, which is a kind of energy","correct_answer":"It takes heat out of the food and passes it to the air behind"}'::jsonb, 'The child thinks cold is a thing that is made.', 'Offer "It makes cold, which is a kind of energy" next to the right answer and ask the question again in a new context.', 'Feel the back of a refrigerator: it is warm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SAFETY.M_ESF_WET_HANDS', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SAFETY', 'Thinks it is safe to switch on with wet hands if the power is low.', '{"question":"A learner has wet hands. What should she do before using a socket?","wrong_answer":"Switch on quickly, it is only a little current","correct_answer":"Dry her hands first"}'::jsonb, 'The child thinks small appliances are harmless.', 'Offer "Switch on quickly, it is only a little current" next to the right answer and ask the question again in a new context.', 'Say that water carries electricity through the skin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SAFETY.M_ESF_UNPLUG_PULL', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SAFETY', 'Thinks you pull on the cable to remove a plug, and that mending a plug is fine for a learner.', '{"question":"How should a plug be removed from a socket?","wrong_answer":"By pulling on the cable","correct_answer":"By switching off, then holding the plug"}'::jsonb, 'The child tugs on the nearest thing.', 'Offer "By pulling on the cable" next to the right answer and ask the question again in a new context.', 'Look at a worn cable.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SAFETY.M_ESF_OVERLOAD', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SAFETY', 'Thinks many appliances in one socket is safe, because there is a switch.', '{"question":"Why is it unsafe to plug many appliances into one socket?","wrong_answer":"It is not unsafe, there is a switch","correct_answer":"The wire can overheat and start a fire"}'::jsonb, 'The child sees the extension lead.', 'Offer "It is not unsafe, there is a switch" next to the right answer and ask the question again in a new context.', 'Say that a wire with too much current gets warm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SOURCES.M_ES_SOLAR_NIGHT', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SOURCES', 'Thinks a solar panel makes electricity at night from the Moon or stored sunlight in the panel.', '{"question":"Does a solar panel make electricity at night?","wrong_answer":"Yes, it stores sunlight in the panel","correct_answer":"No: it makes electricity only in daylight; a battery stores some for the night"}'::jsonb, 'Sees solar lamps shine at night and thinks the panel is working.', 'Offer "Yes, it stores sunlight in the panel" next to the right answer and ask the question again in a new context.', 'Cover a small solar panel with a cloth: the fan or bulb stops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.CIRCUIT_BASICS.M_CB_CELL_ONE_END', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.CIRCUIT_BASICS', 'Thinks a bulb lights if both wires are joined to the same end of the cell.', '{"question":"Both wires from a bulb are joined to the positive end of a cell. Will it light?","wrong_answer":"Yes, both wires touch the cell","correct_answer":"No: one wire must go to each end to make a complete circuit"}'::jsonb, 'Knows the cell is needed but not that current must go round.', 'Offer "Yes, both wires touch the cell" next to the right answer and ask the question again in a new context.', 'Try it: then move one wire to the other end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.SERIES_PARALLEL.M_SP_MORE_BULBS_BRIGHTER', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.SERIES_PARALLEL', 'Thinks adding more bulbs in series makes each bulb brighter.', '{"question":"A second bulb is added in series to a one-bulb circuit. What happens to the brightness?","wrong_answer":"Both are brighter","correct_answer":"Both are dimmer"}'::jsonb, 'Thinks more bulbs means more light from each.', 'Offer "Both are brighter" next to the right answer and ask the question again in a new context.', 'Build it and compare with the one-bulb circuit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.APPLIANCES.M_AP2_IRON_LIGHT', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.APPLIANCES', 'Thinks an electric iron changes electricity mainly into light because it glows when hot.', '{"question":"What is the main useful energy from an electric iron?","wrong_answer":"Light","correct_answer":"Heat"}'::jsonb, 'Sees a glowing indicator light and names the visible output.', 'Offer "Light" next to the right answer and ask the question again in a new context.', 'Feel the warmth from an iron (teacher holds it, away from the skin).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SAFETY.M_ESF_KITE_POWERLINE', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.ELEC_SAFETY', 'Thinks it is safe to fly a kite or climb a tree near power lines if you do not touch the wires.', '{"question":"Is it safe to fly a kite near overhead power lines?","wrong_answer":"Yes, if the kite does not touch the wires","correct_answer":"No: a kite or string can touch or come near the lines and carry a shock; play far away"}'::jsonb, 'Underestimates how easily things reach the wires.', 'Offer "Yes, if the kite does not touch the wires" next to the right answer and ask the question again in a new context.', 'Show a picture of a kite caught on power lines; talk about calling KPLC, not pulling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.MAGNETISM.MAGNET_PROPERTIES.M_MP_LIKE_ATTRACT', 'INTE.G7.FORCE_.MAGNETISM.MAGNET_PROPERTIES', 'Thinks like poles attract and unlike poles repel.', '{"question":"What happens when two north poles are brought together?","wrong_answer":"They attract","correct_answer":"They repel"}'::jsonb, 'The child learns the law backwards.', 'Offer "They attract" next to the right answer and ask the question again in a new context.', 'Push two north poles together and feel the push.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.MAGNETISM.MAGNET_PROPERTIES.M_MP_MIDDLE', 'INTE.G7.FORCE_.MAGNETISM.MAGNET_PROPERTIES', 'Thinks the middle of a bar magnet is the strongest part.', '{"question":"Which part of a bar magnet attracts pins most strongly?","wrong_answer":"The middle","correct_answer":"The two ends, the poles"}'::jsonb, 'The child expects the centre to be the strongest.', 'Offer "The middle" next to the right answer and ask the question again in a new context.', 'Roll a bar magnet in pins and see where they stick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.MAGNETISM.MAGNET_PROPERTIES.M_MP_ONE_POLE', 'INTE.G7.FORCE_.MAGNETISM.MAGNET_PROPERTIES', 'Thinks a magnet can have a single pole, or that cutting it gives one north and one south magnet.', '{"question":"A bar magnet is cut in two. What happens?","wrong_answer":"One piece is a north pole and the other a south pole","correct_answer":"Each piece is a magnet with two poles"}'::jsonb, 'The child pictures poles as halves.', 'Offer "One piece is a north pole and the other a south pole" next to the right answer and ask the question again in a new context.', 'Cut a magnetic strip with scissors and test the pieces.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.MAGNETISM.MAGNETIC_MATERIALS.M_MM_ALL_METALS', 'INTE.G7.FORCE_.MAGNETISM.MAGNETIC_MATERIALS', 'Thinks all metals are magnetic.', '{"question":"Which of these metals is magnetic?","wrong_answer":"Aluminium","correct_answer":"Iron"}'::jsonb, 'The child thinks magnetic and metal mean the same.', 'Offer "Aluminium" next to the right answer and ask the question again in a new context.', 'Test a nail, a coin, a foil wrap and a spoon with a magnet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.MAGNETISM.MAGNETIC_MATERIALS.M_MM_SHINY', 'INTE.G7.FORCE_.MAGNETISM.MAGNETIC_MATERIALS', 'Thinks a shiny object must be magnetic.', '{"question":"A shiny gold-coloured ring is not pulled by a magnet. Why?","wrong_answer":"It is shiny, so it must be magnetic","correct_answer":"The material is not magnetic"}'::jsonb, 'The child links shine with metal.', 'Offer "It is shiny, so it must be magnetic" next to the right answer and ask the question again in a new context.', 'Test shiny and dull objects.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.MAGNETISM.MAGNETIC_MATERIALS.M_MM_HEAVY', 'INTE.G7.FORCE_.MAGNETISM.MAGNETIC_MATERIALS', 'Thinks that heavy objects are more magnetic.', '{"question":"A big, heavy brass bell is not pulled by a magnet. A small iron nail is. Why?","wrong_answer":"The bell is too heavy to be pulled","correct_answer":"Brass is not magnetic and iron is"}'::jsonb, 'The child blames the weight.', 'Offer "The bell is too heavy to be pulled" next to the right answer and ask the question again in a new context.', 'Try a magnet on a light piece of brass.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.MAGNETISM.MAGNET_USES.M_MU_COMPASS_SUN', 'INTE.G7.FORCE_.MAGNETISM.MAGNET_USES', 'Thinks a compass needle points to the Sun or to buried iron.', '{"question":"Which way does a compass needle point?","wrong_answer":"To the Sun","correct_answer":"North and south, along the earth''s magnetic field"}'::jsonb, 'The child links directions with the Sun.', 'Offer "To the Sun" next to the right answer and ask the question again in a new context.', 'Hold a compass in a room and see it still points the same way.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.MAGNETISM.MAGNET_USES.M_MU_FRIDGE_GLUE', 'INTE.G7.FORCE_.MAGNETISM.MAGNET_USES', 'Thinks a refrigerator door seals because of glue.', '{"question":"What holds a refrigerator door shut?","wrong_answer":"A glue on the rubber strip","correct_answer":"A magnet in the rubber seal"}'::jsonb, 'The child cannot see the magnet.', 'Offer "A glue on the rubber strip" next to the right answer and ask the question again in a new context.', 'Pull the door slowly and feel the grip.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.MAGNETISM.MAGNET_USES.M_MU_PICK_ALL', 'INTE.G7.FORCE_.MAGNETISM.MAGNET_USES', 'Thinks a magnet can pick out all the metals in a rubbish heap.', '{"question":"A magnet is passed over a heap of waste. What does it pick out?","wrong_answer":"All the metals, including aluminium cans","correct_answer":"Only iron and steel things, such as nails and tin cans"}'::jsonb, 'The child thinks magnets pick all metals.', 'Offer "All the metals, including aluminium cans" next to the right answer and ask the question again in a new context.', 'Pass a magnet over cans and foil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.MAGNETISM.MAGNET_PROPERTIES.M_MP_THROUGH_NOTHING', 'INTE.G7.FORCE_.MAGNETISM.MAGNET_PROPERTIES', 'Thinks a magnet''s pull cannot pass through paper, plastic, wood or water.', '{"question":"Can a magnet pull a paper clip through a sheet of paper?","wrong_answer":"No, the paper blocks it","correct_answer":"Yes: magnetic force passes through paper, plastic, wood and water"}'::jsonb, 'Thinks a force needs direct contact.', 'Offer "No, the paper blocks it" next to the right answer and ask the question again in a new context.', 'Move a magnet under a sheet of paper with a paper clip on top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.MAGNETISM.MAGNETIC_MATERIALS.M_MM_COIN_ALL', 'INTE.G7.FORCE_.MAGNETISM.MAGNETIC_MATERIALS', 'Thinks all Kenyan coins are magnetic because they are metal.', '{"question":"Will a magnet pick up every coin?","wrong_answer":"Yes, coins are metal","correct_answer":"Only coins with iron or steel in them; test each"}'::jsonb, 'Uses "metal" as the rule.', 'Offer "Yes, coins are metal" next to the right answer and ask the question again in a new context.', 'Test each coin with a magnet and record.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G7.FORCE_.MAGNETISM.MAGNET_USES.M_MU_ELEC_NO_MAGNET', 'INTE.G7.FORCE_.MAGNETISM.MAGNET_USES', 'Does not know that speakers, motors and generators use magnets.', '{"question":"Which part of a phone speaker makes it work with electricity?","wrong_answer":"Only the wires","correct_answer":"A magnet and a coil of wire"}'::jsonb, 'Thinks magnets are only for sticking things.', 'Offer "Only the wires" next to the right answer and ask the question again in a new context.', 'Take apart an old speaker (teacher): find the magnet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
